//! The editable part of a symmetric map (`core/map_editor.md > Symmetry > Editing a symmetric map`: only one half, or
//! one quarter for the four-fold symmetries, is edited; the rest is generated from it).

use std::cmp::Ordering;

use glam::Vec2;

use super::Symmetry;
use crate::units::{CornerPos, SU_PER_GU, TilePos};

/// The part of a `width × height` map that the map maker edits under a symmetry. It holds exactly one element of
/// every set of images (tiles, corners, footprints and points alike), so the rest of the map is generated by mapping
/// it to its images. An element lies in it when its center does:
///
/// | Symmetry | Editable part |
/// |---|---|
/// | None, or one that doesn't fit the map | everything |
/// | Rotate 180 | the west half; on the vertical center line, its north half with the center |
/// | Rotate 90 | the north-west quarter: west of the center and north of it or level with it, plus the center |
/// | Mirror on the vertical axis | the west half with the axis |
/// | Mirror on the horizontal axis | the north half with the axis |
/// | Mirror on both axes | the north-west quarter with the axes |
#[derive(Copy, Clone, Debug, PartialEq, Eq)]
pub struct EditableRegion {
    symmetry: Symmetry,
    width: u32,
    height: u32,
}

impl EditableRegion {
    pub fn new(symmetry: Symmetry, width: u32, height: u32) -> Self {
        let symmetry = if symmetry.fits(width, height) {
            symmetry
        } else {
            Symmetry::None
        };
        Self {
            symmetry,
            width,
            height,
        }
    }

    /// Whether everything is editable (no symmetry).
    pub fn is_everything(&self) -> bool {
        self.symmetry == Symmetry::None
    }

    /// Whether tile `t` is editable.
    pub fn tile(&self, t: TilePos) -> bool {
        self.doubled(2 * i64::from(t.x) + 1, 2 * i64::from(t.y) + 1)
    }

    /// Whether corner `c` is editable.
    pub fn corner(&self, c: CornerPos) -> bool {
        self.doubled(2 * i64::from(c.x), 2 * i64::from(c.y))
    }

    /// Whether the `w × h` footprint with its top-left tile at `origin` is editable: its center is.
    pub fn footprint(&self, origin: TilePos, w: u32, h: u32) -> bool {
        self.doubled(
            2 * i64::from(origin.x) + i64::from(w),
            2 * i64::from(origin.y) + i64::from(h),
        )
    }

    /// Whether point `p` (space units) is editable. Non-finite points never are.
    pub fn point(&self, p: Vec2) -> bool {
        // Exact in f64 for every f32: doubling and dividing by a power of two.
        let doubled = |v: f32, size: u32| f64::from(v) * 2.0 / f64::from(SU_PER_GU) - f64::from(size);
        let (u, v) = (doubled(p.x, self.width), doubled(p.y, self.height));
        match (u.partial_cmp(&0.0), v.partial_cmp(&0.0)) {
            (Some(u), Some(v)) => self.contains(u, v),
            _ => false,
        }
    }

    /// The tiles strictly inside the editable part, as a rectangle from `min` (included) to `max` (excluded): the
    /// whole map, a half or a quarter, without the axes and the center.
    pub fn inner_rect(&self) -> (TilePos, TilePos) {
        let (w, h) = (self.width as i32, self.height as i32);
        let max = match self.symmetry {
            Symmetry::None => (w, h),
            Symmetry::Rotate180 | Symmetry::MirrorVerticalAxis => (w / 2, h),
            Symmetry::MirrorHorizontalAxis => (w, h / 2),
            Symmetry::Rotate90 | Symmetry::MirrorBothAxes => (w / 2, h / 2),
        };
        (TilePos::new(0, 0), TilePos::new(max.0, max.1))
    }

    /// Whether the point at `(x2, y2)` in doubled tile units (so that the map's center is `(width, height)`) is
    /// editable.
    fn doubled(&self, x2: i64, y2: i64) -> bool {
        let u = x2.cmp(&i64::from(self.width));
        let v = y2.cmp(&i64::from(self.height));
        self.contains(u, v)
    }

    /// Whether a point on side `u` of the vertical center line (west is `Less`) and side `v` of the horizontal one
    /// (north is `Less`) is editable.
    fn contains(&self, u: Ordering, v: Ordering) -> bool {
        use Ordering::{Equal, Greater, Less};
        match self.symmetry {
            Symmetry::None => true,
            Symmetry::Rotate180 => u == Less || (u == Equal && v != Greater),
            Symmetry::Rotate90 => (u == Less && v != Greater) || (u == Equal && v == Equal),
            Symmetry::MirrorVerticalAxis => u != Greater,
            Symmetry::MirrorHorizontalAxis => v != Greater,
            Symmetry::MirrorBothAxes => u != Greater && v != Greater,
        }
    }
}

#[cfg(test)]
mod tests {
    use std::collections::BTreeSet;

    use super::*;

    /// The editable part holds exactly one element of every set of images: of tiles, corners, footprints and points.
    #[test]
    fn every_set_of_images_has_exactly_one_editable_element() {
        for (w, h) in [(10, 8), (9, 7), (6, 6), (5, 5), (1, 1), (2, 3)] {
            for s in Symmetry::ALL {
                let Some(transforms) = s.transforms(w, h) else {
                    continue;
                };
                let region = EditableRegion::new(s, w, h);
                for y in -1..=h as i32 + 1 {
                    for x in -1..=w as i32 + 1 {
                        let tiles: BTreeSet<TilePos> = transforms.iter().map(|m| m.tile(TilePos::new(x, y))).collect();
                        let editable = tiles.iter().filter(|t| region.tile(**t)).count();
                        assert_eq!(editable, 1, "{s:?} {w}x{h} tile ({x}, {y})");
                        let corners: BTreeSet<CornerPos> =
                            transforms.iter().map(|m| m.corner(CornerPos::new(x, y))).collect();
                        let editable = corners.iter().filter(|c| region.corner(**c)).count();
                        assert_eq!(editable, 1, "{s:?} {w}x{h} corner ({x}, {y})");
                        for (fw, fh) in [(2, 2), (3, 1), (2, 3)] {
                            let footprints: BTreeSet<(TilePos, u32, u32)> = transforms
                                .iter()
                                .map(|m| m.footprint(TilePos::new(x, y), fw, fh))
                                .collect();
                            // A footprint that partly overlaps an image of itself is refused anyway (e.g. a 3x1
                            // footprint on the center of a 90 degree map: its images form a cross).
                            let covers = |(o, w, h): &(TilePos, u32, u32)| -> BTreeSet<TilePos> {
                                (0..*h as i32)
                                    .flat_map(|dy| (0..*w as i32).map(move |dx| TilePos::new(o.x + dx, o.y + dy)))
                                    .collect()
                            };
                            let sets: Vec<BTreeSet<TilePos>> = footprints.iter().map(covers).collect();
                            let overlapping = sets
                                .iter()
                                .enumerate()
                                .any(|(i, a)| sets[i + 1..].iter().any(|b| !a.is_disjoint(b)));
                            if overlapping {
                                continue;
                            }
                            let editable = footprints
                                .iter()
                                .filter(|(o, w, h)| region.footprint(*o, *w, *h))
                                .count();
                            assert_eq!(editable, 1, "{s:?} {w}x{h} footprint ({x}, {y}) {fw}x{fh}");
                        }
                        let p = Vec2::new(x as f32 * 32.0 + 3.0, y as f32 * 32.0);
                        let points: Vec<Vec2> = transforms.iter().map(|m| m.point(p)).collect();
                        let mut distinct: Vec<Vec2> = Vec::new();
                        for q in points {
                            if !distinct.contains(&q) {
                                distinct.push(q);
                            }
                        }
                        let editable = distinct.iter().filter(|q| region.point(**q)).count();
                        assert_eq!(editable, 1, "{s:?} {w}x{h} point {p}");
                    }
                }
            }
        }
    }

    #[test]
    fn the_editable_part_is_a_half_or_a_quarter() {
        let count = |s: Symmetry, w: u32, h: u32| {
            let region = EditableRegion::new(s, w, h);
            (0..h as i32)
                .flat_map(|y| (0..w as i32).map(move |x| TilePos::new(x, y)))
                .filter(|t| region.tile(*t))
                .count()
        };
        assert_eq!(count(Symmetry::None, 10, 8), 80);
        assert_eq!(count(Symmetry::Rotate180, 10, 8), 40);
        assert_eq!(count(Symmetry::MirrorVerticalAxis, 10, 8), 40);
        assert_eq!(count(Symmetry::MirrorHorizontalAxis, 10, 8), 40);
        assert_eq!(count(Symmetry::MirrorBothAxes, 10, 8), 20);
        assert_eq!(count(Symmetry::Rotate90, 8, 8), 16);
        // Odd sides: the middle column or row belongs to the editable part where it is its own image.
        assert_eq!(count(Symmetry::MirrorVerticalAxis, 9, 2), 10);
        assert_eq!(count(Symmetry::Rotate180, 9, 3), 14);
        assert_eq!(count(Symmetry::Rotate90, 5, 5), 7);
        // West is editable, east is generated.
        let r = EditableRegion::new(Symmetry::Rotate180, 10, 8);
        assert!(r.tile(TilePos::new(4, 7)) && !r.tile(TilePos::new(5, 0)));
        assert_eq!(r.inner_rect(), (TilePos::new(0, 0), TilePos::new(5, 8)));
        // A symmetry that doesn't fit the map leaves everything editable.
        assert!(EditableRegion::new(Symmetry::Rotate90, 10, 8).is_everything());
        assert!(!r.point(Vec2::NAN));
    }
}
